function esc(s){ return (s||"").replace(/[&<>"]/g, function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]; }); }
function safeUrl(u){ return /^https?:\/\//i.test(u||"") ? u : ""; }
function host(u){ try { return new URL(u).hostname.replace(/^www\./,""); } catch(e){ return "link"; } }
function link(u){ var s=safeUrl(u); return s ? '<a class="src" target="_blank" rel="noopener noreferrer" title="'+esc(s)+'" href="'+esc(s)+'">'+esc(host(s))+'</a>' : ''; }
function links(arr){ arr=arr||[]; var p=[]; for(var i=0;i<arr.length;i++){ var h=link(arr[i]); if(h) p.push(h); } return p.join(' <span class="sub">·</span> '); }
function srcCell(r){ return links((r.urls&&r.urls.length)?r.urls:(r.url?[r.url]:[])); }
function bucket(s){ s=(s||"").trim().toLowerCase();
  if(s===""||s==="\u2014"||s==="-") return "none";
  if(s.indexOf("not affected")>=0||s.indexOf("not vuln")>=0) return "ok";
  if(s.indexOf("mitigation")>=0) return "info";
  if(s.indexOf("investigation")>=0) return "warn";
  if(s.indexOf("fix")>=0) return "fix";
  if(s.indexOf("vulnerable")>=0||s.indexOf("affected")>=0) return "crit";
  return "none"; }
var SEV={crit:5,warn:4,info:3,fix:2,ok:1,none:0};
function cb(r){ var a=bucket(r.s), b=bucket(r.s2||r.s); return SEV[a]>=SEV[b]?a:b; }
var PCLASS={crit:"p-crit",fix:"p-fix",warn:"p-warn",ok:"p-ok",info:"p-info",none:"p-none"};
var LBL={crit:"Vulnerable / Affected",fix:"Fix available",warn:"Investigation",info:"Mitigation",ok:"Not affected",none:"Reference"};
function pill(s){ var b=bucket(s); var txt=(b==="none")?"Reference":esc(s); return '<span class="pill '+PCLASS[b]+'">'+txt+'</span>'; }
function statusCell(r){ var a=(r.s||""), b=(r.s2||r.s||"");
  if(a.trim().toLowerCase()===b.trim().toLowerCase()) return pill(a);
  return pill(a)+' <span class="sub">/</span> '+pill(b); }
DATA.actionable = DATA.full.filter(function(r){ var k=cb(r); return k==="crit"||k==="fix"; });
var NOTES={ actionable:"Entries that are Vulnerable or have a Fix for either CVE \u2014 the rows worth acting on.",
  full:"Complete NCSC-NL inventory, every status including investigation leads.",
  index:"A\u2013Z directory of every supplier on the list, with product counts, a status mix, and a link to the supplier's page in the NCSC-NL source." };
function ncscLetter(s){ var c=(s||"").trim().charAt(0).toLowerCase(); return (c>="a"&&c<="z")?c:"0-9"; }
function ncscUrl(s){ return "https://github.com/NCSC-NL/php2shell/blob/main/software/software_list_"+ncscLetter(s)+".md"; }
function buildIndex(){ var m={}; DATA.full.forEach(function(r){ var s=r.supplier||"(unknown)"; if(!m[s]) m[s]={supplier:s,n:0,b:{crit:0,fix:0,warn:0,ok:0,info:0,none:0}}; m[s].n++; m[s].b[cb(r)]++; });
  return Object.keys(m).sort(function(a,b){a=a.toLowerCase();b=b.toLowerCase();return a<b?-1:(a>b?1:0);}).map(function(k){return m[k];}); }
function recount(){ $("c-actionable").textContent=DATA.actionable.length; $("c-full").textContent=DATA.full.length;
  var set={}; DATA.full.forEach(function(r){set[r.supplier]=1;}); $("c-index").textContent=Object.keys(set).length; }
function rows(){ var term=$("q").value.trim().toLowerCase(), filt=$("sf").value;
  return DATA[view].filter(function(r){
    if(term && (r.supplier+" "+r.product).toLowerCase().indexOf(term)<0) return false;
    if(filt && cb(r)!==filt) return false; return true; }); }
var ORDER=["crit","fix","warn","info","ok","none"];
function setStatusOptions(){ var seen={}, sf=$("sf"); sf.innerHTML='<option value="">All statuses</option>';
  var src = (view==="index") ? DATA.full : DATA[view];
  src.forEach(function(r){ seen[cb(r)]=1; });
  ORDER.forEach(function(b){ if(seen[b]) sf.insertAdjacentHTML("beforeend",'<option value="'+b+'">'+LBL[b]+'</option>'); }); }
function renderTiles(list){ var c={crit:0,fix:0,warn:0,ok:0,info:0,none:0}; list.forEach(function(r){ c[cb(r)]++; });
  var defs=[["crit","Vulnerable","crit"],["fix","Fix avail.","fix"],["warn","Investigation","warn"],["info","Mitigation","ok"],["ok","Not affected","ok"],["none","Reference",""]];
  $("tiles").innerHTML=defs.filter(function(d){return c[d[0]]>0;}).map(function(d){ return '<div class="tile '+d[2]+'"><div class="n">'+c[d[0]]+'</div><div class="l">'+d[1]+'</div></div>'; }).join(""); }
function renderIndex(){ var term=$("q").value.trim().toLowerCase(), filt=$("sf").value;
  var idx=buildIndex().filter(function(e){ if(term && e.supplier.toLowerCase().indexOf(term)<0) return false; if(filt && !(e.b[filt]>0)) return false; return true; });
  $("tiles").innerHTML='<div class="tile acc"><div class="n">'+idx.length+'</div><div class="l">Suppliers shown</div></div>';
  $("thead").innerHTML="<tr><th>Supplier</th><th>Products</th><th>Status mix</th><th>NCSC-NL source</th></tr>";
  $("tbody").innerHTML=idx.length?idx.map(function(e){
    var mix=ORDER.filter(function(b){return e.b[b]>0;}).map(function(b){return '<span class="pill '+PCLASS[b]+'">'+e.b[b]+' '+LBL[b].replace(" / Affected","")+'</span>';}).join(" ");
    var u=ncscUrl(e.supplier);
    return "<tr><td class='v'>"+esc(e.supplier)+"</td><td class='num'>"+e.n+"</td><td><div class='mix'>"+mix+"</div></td><td><a class='src' target='_blank' rel='noopener noreferrer' href='"+esc(u)+"'>software_list_"+esc(ncscLetter(e.supplier))+".md</a></td></tr>";
  }).join(""):"<tr><td class='empty' colspan='4'>No suppliers match.</td></tr>"; }
function render(){ $("viewnote").textContent=NOTES[view];
  if(view==="index"){ renderIndex(); return; }
  var list=rows(); renderTiles(list);
  $("thead").innerHTML="<tr><th>Supplier</th><th>Product</th><th>Status</th><th>Note</th><th>Source</th></tr>";
  $("tbody").innerHTML=list.length?list.map(function(r){ return "<tr><td class='v'>"+esc(r.supplier)+"</td><td>"+esc(r.product)+"</td><td>"+statusCell(r)+"</td><td class='sub'>"+esc(r.note)+"</td><td>"+srcCell(r)+"</td></tr>"; }).join(""):"<tr><td class='empty' colspan='5'>No rows match.</td></tr>"; }
$("tabs").addEventListener("click",function(e){ var b=e.target.closest(".tab"); if(!b) return; view=b.getAttribute("data-view");
  Array.prototype.forEach.call($("tabs").children,function(t){ t.setAttribute("aria-selected", t===b?"true":"false"); }); setStatusOptions(); render(); });
$("q").addEventListener("input",render); $("sf").addEventListener("change",render);
$("tabs").querySelector('[data-view=actionable]').setAttribute("aria-selected","true");
recount(); setStatusOptions(); render();


var LETTERS="0-9 a b c d e f g h i j k l m n o p q r s t u v w x y z".split(" ");
var BASE="https://raw.githubusercontent.com/NCSC-NL/php2shell/main/software/software_list_";
function parseMd(txt,out){ txt.split("\n").forEach(function(line){ if(line.charAt(0)!=="|") return;
  var body=line.trim(); if(body.charAt(0)==="|") body=body.slice(1); if(body.charAt(body.length-1)==="|") body=body.slice(0,-1);
  var c=body.split(/(?<!\\)\|/).map(function(x){return x.replace(/\\\|/g,"|").trim();});
  if(c.length<5) return; if(c[0].toLowerCase()==="supplier") return; if(/^[:\-\s]+$/.test(c.join(""))) return;
  var found=[],re=/\(<?(https?:\/\/[^)>\s]+)>?\)/g,mm; while((mm=re.exec(line))){found.push(mm[1]);}
  var human=[],code=[],i; for(i=0;i<found.length;i++){ (found[i].indexOf("raw.githubusercontent.com")<0?human:code).push(found[i]); }
  var urls=[]; human.concat(code).forEach(function(u){ if(urls.indexOf(u)<0) urls.push(u); });
  out.push({supplier:c[0],product:c[1],s:(c[3]||"\u2014"),s2:(c[4]||"\u2014"),note:(c[5]||"").split(/<br\s*\/?>/i)[0].trim(),url:(urls[0]||""),urls:urls}); }); }
function tnow(){ try{ return new Date().toLocaleTimeString([], {timeZoneName:"short"}); }catch(e){ return new Date().toLocaleTimeString(); } }
function goLive(){ var dot=$("dot"),txt=$("livetxt"); if(dot){dot.className="dot loading";} if(txt){txt.textContent="Fetching live\u2026";}
  Promise.all(LETTERS.map(function(L){ return fetch(BASE+L+".md",{cache:"no-store"}).then(function(r){return r.ok?r.text():null;}).catch(function(){return null;}); }))
  .then(function(parts){ var okn=0,out=[]; parts.forEach(function(t){ if(t){ okn++; parseMd(t,out); } });
    if(okn===0) throw new Error("all requests blocked");
    DATA.full=out; DATA.actionable=out.filter(function(r){ var k=cb(r); return k==="crit"||k==="fix"; });
    if(okn<LETTERS.length){ if(dot){dot.className="dot stale";} if(txt){txt.textContent="LIVE "+okn+"/"+LETTERS.length+" lists \u00b7 "+tnow()+" ("+out.length+" products)";} }
    else { if(dot){dot.className="dot live";} if(txt){txt.textContent="LIVE \u00b7 "+tnow()+" ("+out.length+" products)";} }
  }).catch(function(e){ if(dot){dot.className="dot stale";} if(txt){txt.textContent="Snapshot 2026-10-23 15:13 Cairo (UTC+3) (live blocked: "+e.message+")";}
  }).then(function(){ recount(); setStatusOptions(); render(); });
}
if($("refresh")) $("refresh").addEventListener("click",goLive);
goLive();
